certificationWidget.script:
window.addEventListener('load', function () {
    document.body.insertAdjacentHTML('beforeend', '<style>    #cik-widget {        box-sizing: border-box !important;        font-family: "Trebuchet MS", "Lucida Grande", Tahoma, sans-serif !important;        font-size: 14px !important;        font-weight: normal !important;        line-height: 20px !important;        color: #343434 !important;    }    #cik-widget a {        color: #343434 !important;        text-decoration: none !important;    }    #cik-widget * {        box-sizing: border-box !important;    }    #cik-widget ul {        list-style: none !important;        margin: 10px !important;        padding: 0 !important;    }    #cik-widget ul li {        position: relative !important;        margin: 5px 0 !important;        padding: 0 0 0 30px !important;    }    #cik-widget ul li::before {        content: "" !important;        position: absolute !important;        top: 2px !important;        left: 7px !important;        display: inline-block !important;        transform: rotate(40deg) !important;        height: 13px !important;        width: 6px !important;        box-sizing: border-box !important;        border-bottom: 2px solid #da251c !important;        border-right: 2px solid #da251c !important;    }    #cik-widget ul li::after {        content: "" !important;        position: absolute !important;        top: 0 !important;        left: 0 !important;        border: 2px solid #da251c !important;        width: 20px !important;        height: 20px !important;        box-sizing: border-box !important;    }    #cik-widget .cik-widget-header {        margin: 10px !important;        padding: 0 !important;        font-size: 16px !important;        font-weight: bold !important;    }            #cik-widget {        position: fixed !important;        bottom: 100px !important;        z-index: 9999 !important;        width: 400px !important;        min-height: 260px !important;        background: #fff !important;        border-top: 5px solid #da251c !important;        border-bottom: 5px solid #da251c !important;        outline: 2px solid #fff !important;    }    #cik-widget #cik-widget-logo {        position: absolute !important;        top: 10px !important;    }    #cik-widget #cik-widget-header {        position: absolute !important;        top: calc(50% - 15px) !important;        text-align: center !important;        font-size: 16px !important;        color: #fff !important;    }    #cik-widget #cik-widget-close {        display: none !important;    }    #cik-widget #cik-widget-arrow {        position: absolute !important;        bottom: 15px !important;        display: inline-block !important;        width: 45px !important;        font-size: 36px !important;        color: #fff !important;    }                #cik-widget {        right: -350px !important;        border-left: 50px solid #da251c !important;        border-radius: 20px 0 0 20px;        transition: right 0.5s !important;    }    #cik-widget:hover {        right: 0 !important;    }    #cik-widget #cik-widget-logo {        left: -48px !important;    }    #cik-widget #cik-widget-header {        left: -93px !important;        transform: rotate(-90deg) !important;    }    #cik-widget #cik-widget-arrow {        left: -35px !important;    }        </style><div id="cik-widget">    <div id="cik-widget-container">                <img id="cik-widget-logo" src="data:image/png;base64," />                <div id="cik-widget-header">            Certyfikowane<br />            Biuro Rachunkowe            <div id="cik-widget-close">✕</div>        </div>        <div id="cik-widget-arrow">«</div>        <a href="https://www.cik.org.pl/biuro/omega-monika-glonek-28162" target="_blank">            <div class="cik-widget-header">Kryteria C.I.K.</div>            <ul>                <li>Uprawnienia: Certyfikat Księgowy nr 54701/2012</li>                <li>Ubezpieczenie OC: Leadenhall</li>                <li>Brak zaległości finansowych w BIG</li>                <li>Nienaganna opinia</li>                <li>Licencjonowany program księgowy: InsERT</li>                <li>Min. 2 lata doświadczenia (od 2017-08-02)</li>            </ul>                        <div class="cik-widget-header">Dodatkowe informacje</div>            <ul>                                <li>Ostatnia weryfikacja wiedzy podatkowej: 2026 - czerwiec</li>                                            </ul>                    </a>    </div></div>');
    document.getElementById('cik-widget-logo').addEventListener('click', function () {
        document.getElementById('cik-widget').classList.add('cik-widget-active');
    });
    document.getElementById('cik-widget-close').addEventListener('click', function () {
        document.getElementById('cik-widget').classList.remove('cik-widget-active');
    });
    console.log('widget displayed');
});
